<?php
require_once 'config/database.php';require_once 'includes/functions.php';verifyCsrf();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){$pid=(int)($_POST['product_id']??0);$type=$_POST['type']??'';$qty=(int)($_POST['quantity']??0);$note=trim($_POST['note']??'');if(!$pid)$errors[]='Pilih produk.';if(!in_array($type,['masuk','keluar'],true))$errors[]='Jenis transaksi tidak valid.';if($qty<1)$errors[]='Jumlah harus minimal 1.';if(!$errors){try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT stock FROM products WHERE id=? FOR UPDATE");$q->execute([$pid]);$p=$q->fetch();if(!$p)throw new Exception('Produk tidak ditemukan.');if($type==='keluar'&&$p['stock']<$qty)throw new Exception('Stok tidak mencukupi. Stok tersedia: '.$p['stock']);$new=$type==='masuk'?$p['stock']+$qty:$p['stock']-$qty;$pdo->prepare("UPDATE products SET stock=? WHERE id=?")->execute([$new,$pid]);$pdo->prepare("INSERT INTO stock_transactions(product_id,type,quantity,note) VALUES(?,?,?,?)")->execute([$pid,$type,$qty,$note]);$pdo->commit();flash('success','Perubahan stok berhasil dicatat.');redirect('stock.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e->getMessage();}}}
$products=$pdo->query("SELECT id,name,sku,stock FROM products ORDER BY name")->fetchAll();$pageTitle='Stok Barang';require 'includes/header.php';?>
<div class="page-tools"><p class="muted">Catat barang masuk dan keluar. Stok produk akan diperbarui otomatis.</p></div>
<div class="two-column stock-layout"><section class="form-panel"><div class="panel-head"><div><span class="eyebrow">STOCK ADJUSTMENT</span><h3>Catat Pergerakan Stok</h3><p class="muted">Pilih produk dan masukkan jumlah perubahan stok.</p></div></div><?php if($errors): ?><div class="alert error"><?= implode('<br>',array_map('e',$errors)) ?></div><?php endif; ?>
<form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><label>Produk<select name="product_id" required><option value="">Pilih produk</option><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>" <?= (int)($_POST['product_id']??0)===$p['id']?'selected':'' ?>><?= e($p['name']) ?> — stok <?= $p['stock'] ?></option><?php endforeach; ?></select></label><label>Jenis Pergerakan<select name="type" required><option value="masuk">Stok Masuk (+)</option><option value="keluar" <?= ($_POST['type']??'')==='keluar'?'selected':'' ?>>Stok Keluar (−)</option></select></label><label>Jumlah Unit<input type="number" name="quantity" min="1" required value="<?= e($_POST['quantity']??'1') ?>"></label><label>Catatan<textarea name="note" rows="3" placeholder="Contoh: Restock dari supplier..."><?= e($_POST['note']??'') ?></textarea></label><button class="btn btn-primary">Simpan Perubahan Stok</button></form></section>
<section class="panel"><div class="panel-head"><div><span class="eyebrow">CURRENT INVENTORY</span><h3>Posisi Stok</h3></div><span class="count-chip"><?= count($products) ?> produk</span></div><div class="category-list"><?php foreach($products as $p): ?><div class="category-row"><div class="product-initial"><?= e(strtoupper(substr($p['name'],0,1))) ?></div><div class="category-info"><strong><?= e($p['name']) ?></strong><small><?= e($p['sku']) ?></small></div><span class="stock-pill <?= $p['stock']<=5?'warning':'' ?>"><?= (int)$p['stock'] ?> unit</span></div><?php endforeach; ?><?php if(!$products): ?><div class="empty-state compact">Tambahkan produk terlebih dahulu.</div><?php endif; ?></div></section></div>
<?php require 'includes/footer.php'; ?>
